import { z } from "zod";

import { categoryIdSchema } from "@/lib/category-validation";
import { isValidLocalDate, isValidLocalTime } from "@/lib/local-time";
import { MAX_DEADLINE_OFFSET_DAYS, RECURRENCE_TYPES } from "@/lib/recurrence/rules";
import { MAX_ESTIMATED_MINUTES } from "@/lib/task-rules";

// Ids are generated by the database (cuid); anything else is refused early.
export const idSchema = z.string().regex(/^[a-z0-9]{20,40}$/);

const localDate = z.string().refine(isValidLocalDate, "Please enter a valid date.");
const localTime = z.string().refine(isValidLocalTime, "Please enter a valid time, for example 14:30.");
const weekdays = z.array(z.number().int().min(1).max(7)).max(7);

// Converting an ordinary task: everything else (planned date/time, deadline,
// template) comes from the task itself.
export const convertInputSchema = z
  .object({
    type: z.enum(RECURRENCE_TYPES),
    weekdays: weekdays.optional(),
    endDate: localDate.nullable().optional(),
  })
  .strict();
export type ConvertInput = z.input<typeof convertInputSchema>;

// "This and future tasks". `.strict()` rejects unknown fields, so a tampered
// request (userId, state, version …) is refused instead of silently ignored.
export const seriesPatchSchema = z
  .object({
    // template
    title: z.string().trim().min(1, "Please enter a title.").max(200).optional(),
    description: z.string().trim().max(5000).transform((value) => value || null).nullable().optional(),
    importance: z.enum(["HIGH", "NORMAL", "LOW"]).optional(),
    estimatedMinutes: z.number().int().min(1).max(MAX_ESTIMATED_MINUTES).nullable().optional(),
    categoryId: categoryIdSchema.nullable().optional(),
    // schedule (needs the instance being edited)
    type: z.enum(RECURRENCE_TYPES).optional(),
    weekdays: weekdays.optional(),
    monthlyDay: z.number().int().min(1).max(31).nullable().optional(),
    plannedTime: localTime.nullable().optional(),
    deadlineOffsetDays: z.number().int().min(-MAX_DEADLINE_OFFSET_DAYS).max(MAX_DEADLINE_OFFSET_DAYS).nullable().optional(),
    deadlineTime: localTime.nullable().optional(),
  })
  .strict();
export type SeriesPatch = z.input<typeof seriesPatchSchema>;

export const TEMPLATE_FIELDS = ["title", "description", "importance", "estimatedMinutes", "categoryId"] as const;
export const SCHEDULE_FIELDS = ["type", "weekdays", "monthlyDay", "plannedTime", "deadlineOffsetDays", "deadlineTime"] as const;

export const pauseUntilSchema = localDate.nullable().optional();
export const endDateSchema = localDate.nullable();
export const versionSchema = z.number().int().min(1);
